def page(content):
	fast_layout = LAYOUT.replace("<body>", "<body><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script>", 1).replace("</body><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js' integrity='sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=' crossorigin=''></script></body>", "</body>")
	content = content.replace('centers."', 'centers["').replace('"||centers.Indore', '"]||centers.Indore')
	if "id='real-map'" in content:
		content = content.replace("</section></main></div><script>", COMPLAINT_HTML + "</section></main></div><script>")
		content += COMPLAINT_SCRIPT
	if "id='real-map'" in content:
		fast_layout = fast_layout.replace("<script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script>", "")
		start = content.find("<script>const centers=")
		end = content.find("</script>", start) + len("</script>")
		google_script = f"<script async defer src='https://maps.googleapis.com/maps/api/js?key={GOOGLE_MAPS_API_KEY}&callback=initCivicMap'></script>"
		content = content[:start] + "<script>" + GOOGLE_MAP_SCRIPT + "</script>" + content[end:]
		if not GOOGLE_MAPS_API_KEY:
			content = content.replace("Loading city updates...", "Add GOOGLE_MAPS_API_KEY to enable Google Maps")
		fast_layout = fast_layout.replace("</body>", google_script + "</body>", 1)
	return render_template_string(fast_layout, style=STYLE + COMPLAINT_STYLE, content=content)

def connection():
	db = sqlite3.connect(DB)
	db.row_factory = sqlite3.Row
	db.execute("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT,mobile TEXT UNIQUE,email TEXT,password TEXT,city TEXT,language TEXT)")
	db.execute("CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,user_id INTEGER,category TEXT,description TEXT,photo_name TEXT,created_at TEXT)")
	try:
		db.execute("ALTER TABLE reports ADD COLUMN photo_name TEXT")
	except sqlite3.OperationalError:
		pass
	db.commit()
	return db

def logged_in(view):
	@wraps(view)
	def wrapped(*args, **kwargs):
		return view(*args, **kwargs) if session.get("user_id") else redirect(url_for("login"))
	return wrapped

@app.route("/healthz")
def healthz():
	return jsonify(ok=True)

@app.route("/")
def home():
	if session.get("user_id"):
		return redirect(url_for("dashboard"))
