@app.route("/dashboard")
@logged_in
def dashboard():
	db = connection(); user = db.execute("SELECT * FROM users WHERE id=?", (session["user_id"],)).fetchone(); reports = db.execute("SELECT COUNT(*) FROM reports WHERE user_id=?", (session["user_id"],)).fetchone()[0]; db.close()
	content = render_template_string("""<div class='dashboard'><nav class='dash-nav'><a class='brand' href='/'><span class='mark'>C</span>CivicHub</a><div class='dash-actions'><select id='city'><option>Indore</option><option>Bengaluru</option><option>Jaipur</option><option>Delhi NCR</option><option>Mumbai</option><option>Pune</option><option>Hyderabad</option><option>Chennai</option><option>Kolkata</option><option>Ahmedabad</option></select><select id='language'>{% for language in languages %}<option>{{ language }}</option>{% endfor %}</select><a class='logout' href='/logout'>Log out ↪</a></div></nav><main class='dash-main'><div class='eyebrow'>YOUR CIVIC COMPANION · TODAY</div><h1>Good morning, {{ user['name'].split(' ')[0] }}.</h1><div class='grid'><section class='welcome'><div class='eyebrow' style='color:#c6ddd5'>YOUR CIVIC SNAPSHOT</div><h2>Everything local,<br>at a glance.</h2><p id='city-message'>You are exploring {{ user['city'] }}. Here are the services and updates closest to your day.</p><button class='button' style='background:#d7eb89;color:#123b37' onclick="document.getElementById('map').scrollIntoView()">Explore the city map ↗</button></section><section class='assistant'><div class='eyebrow'>AI CITY ASSISTANT</div><h2>What would you like to know?</h2><p>Ask about buses, government services, hospitals or anything local.</p><div class='ask'><input id='question' placeholder='Ask CivicHub...'><button onclick='askCity()'>Ask</button></div></section></div><div class='metrics'><div class='metric'><small>OPEN REPORTS NEARBY</small><strong>24</strong><span>3 need attention</span></div><div class='metric'><small>AIR QUALITY</small><strong>42</strong><span>Good for outdoor plans</span></div><div class='metric'><small>TRAFFIC</small><strong>Moderate</strong><span>+12 min on main route</span></div><div class='metric'><small>YOUR REPORTS</small><strong>{{ reports }}</strong><span>Track your civic action</span></div></div><div class='grid'><section class='panel'><div class='eyebrow'>FIND A SERVICE</div><h2>What do you need today?</h2><div class='services'><a class='service' href='#map'>⌖ Hospitals & pharmacies</a><a class='service' href='tel:112'>🚑 Emergency contacts</a><a class='service' href='#map'>▱ Bus routes & Chalo</a><a class='service' href='#jobs'>↗ Jobs & internships</a><a class='service' href='https://www.india.gov.in/' target='_blank'>◎ Government services</a><a class='service' href='#report'>+ Report a civic issue</a></div><div class='mapbox' id='map'><div id='real-map'></div><div class='map-overlay'><b>REAL MAP · OPENSTREETMAP</b><span id='map-status'>Loading city updates...</span></div></div><div class='updates-panel'><div class='updates-heading'><b>LIVE CITY UPDATES</b><small id='last-updated'>Checking now...</small></div><div id='updates-list'></div></div></section><section class='panel' id='jobs'><div class='eyebrow'>LOCAL OPPORTUNITIES</div><h2>Jobs & internships</h2><p><b>Frontend intern · Civic startup</b><br><small>Indore · Posted 2 days ago</small></p><p><b>Community coordinator</b><br><small>Palasia · Full time</small></p><a href='#jobs' style='color:#0e6258;font-weight:700'>Browse opportunities ↗</a></section></div><section class='panel report' id='report'><div class='eyebrow'>CITIZEN ACTION</div><h2>Report a public issue</h2><div class='notice'>Your report is saved to your CivicHub account so you can track its status.</div><form class='stack' method='post' action='/report'><label>Issue type<select name='category'><option>Pothole or damaged road</option><option>Garbage or overflowing bin</option><option>Broken streetlight</option><option>Water leakage or shortage</option><option>Broken footpath</option><option>Other public complaint</option></select></label><label>What did you see?<textarea name='description' required placeholder='Add a short description...'></textarea></label><button class='button'>Submit report ↗</button></form></section></main></div><script>const centers={Indore:[22.7196,75.8577],Bengaluru:[12.9716,77.5946],Jaipur:[26.9124,75.7873],'Delhi NCR':[28.6139,77.2090],Mumbai:[19.0760,72.8777],Pune:[18.5204,73.8567],Hyderabad:[17.3850,78.4867],Chennai:[13.0827,80.2707],Kolkata:[22.5726,88.3639],Ahmedabad:[23.0225,72.5714]};const map=L.map('real-map').setView(centers.{{ user['city']|tojson }}||centers.Indore,13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);let updateMarkers=[];let cityMarker=L.marker(map.getCenter()).addTo(map).bindPopup('<b>Your selected city</b><br>CivicHub map centre');function renderUpdates(data){updateMarkers.forEach(marker=>map.removeLayer(marker));updateMarkers=[];const list=document.getElementById('updates-list');list.innerHTML='';(data.updates||[]).forEach(update=>{const color=update.severity==='high'?'#e66d52':update.severity==='moderate'?'#e0aa32':'#3e9b70';const marker=L.circleMarker([update.lat,update.lng],{radius:9,color:'#fff',weight:2,fillColor:color,fillOpacity:.95}).addTo(map).bindPopup('<b>'+update.title+'</b><br>'+update.body);updateMarkers.push(marker);list.innerHTML+=`<div class='update-row'><span style='background:${color}'></span><div><b>${update.title}</b><small>${update.body}</small></div><em>${update.type}</em></div>`});document.getElementById('last-updated').textContent='Updated '+data.updated_at;document.getElementById('map-status').textContent=(data.updates||[]).length+' current advisories · refreshes every 30 seconds'}async function loadUpdates(){const city=document.getElementById('city').value;const response=await fetch('/api/city-updates?city='+encodeURIComponent(city));renderUpdates(await response.json())}document.getElementById('city').onchange=()=>{const city=document.getElementById('city').value;document.getElementById('city-message').textContent='You are exploring '+city+'. Here are the services and updates closest to your day.';map.setView(centers[city]||centers.Indore,13);cityMarker.setLatLng(map.getCenter());loadUpdates()};document.getElementById('language').onchange=e=>alert('CivicHub language set to '+e.target.value);function askCity(){let q=document.getElementById('question');if(q.value)alert('CivicHub found useful city services for: '+q.value);q.value=''}if(navigator.geolocation){navigator.geolocation.getCurrentPosition(position=>{const here=[position.coords.latitude,position.coords.longitude];L.circleMarker(here,{radius:9,color:'#fff',weight:3,fillColor:'#0e6258',fillOpacity:1}).addTo(map).bindPopup('<b>Your live location</b>').openPopup();map.setView(here,14)},()=>{})}loadUpdates();setInterval(loadUpdates,30000)</script>""", user=user, reports=reports, languages=LANGUAGES)
	return page(content)

@app.route("/report", methods=["POST"])
@logged_in
def report():
	photo = request.files.get("photo")
	photo_name = None
	if photo and photo.filename:
		photo_name = f"{session['user_id']}_{datetime.now().strftime('%Y%m%d%H%M%S')}_{secure_filename(photo.filename)}"
		photo.save(UPLOAD_DIR / photo_name)
	db = connection(); db.execute("INSERT INTO reports(user_id,category,description,photo_name,created_at) VALUES(?,?,?,?,?)", (session["user_id"], request.form["category"], request.form["description"], photo_name, datetime.now().isoformat(timespec="seconds"))); db.commit(); db.close(); return redirect(url_for("dashboard"))

